import{_ as i,c as a,ag as e,o as t}from"./chunks/framework.BMGgE9iy.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"outline":"deep","showVersion":false},"headers":[],"relativePath":"update/upgrade-0.13.0.md","filePath":"update/upgrade-0.13.0.md"}'),l={name:"update/upgrade-0.13.0.md"};function h(n,s,p,k,d,r){return t(),a("div",null,s[0]||(s[0]=[e('<p>本篇文檔將介紹如何從 <code>0.12.0</code> 版本升級到 <code>0.13.0</code>。</p><blockquote><p>本次更新並未對語法進行變動，目前語法基本趨於穩定！</p></blockquote><h2 id="標準庫" tabindex="-1">標準庫 <a class="header-anchor" href="#標準庫" aria-label="Permalink to &quot;標準庫&quot;">​</a></h2><h3 id="batbadbut-漏洞臨時方案" tabindex="-1"><code>BatBadBut</code> 漏洞臨時方案 <a class="header-anchor" href="#batbadbut-漏洞臨時方案" aria-label="Permalink to &quot;`BatBadBut` 漏洞臨時方案&quot;">​</a></h3><p><code>std.process.Child</code>：針對 Windows 上的任意命令執行漏洞 (BatBadBut) 的臨時解決方案！</p><p>更多信息可以見該 <a href="https://github.com/ziglang/zig/pull/19698" target="_blank" rel="noreferrer">Issue</a> 和該文章 <a href="https://flatt.tech/research/posts/batbadbut-you-cant-securely-execute-commands-on-windows/" target="_blank" rel="noreferrer">BatBadBut: You can&#39;t securely execute commands on Windows</a>。</p><h3 id="簡化-hash-crc-實現" tabindex="-1">簡化 <code>hash.crc</code> 實現 <a class="header-anchor" href="#簡化-hash-crc-實現" aria-label="Permalink to &quot;簡化 `hash.crc` 實現&quot;">​</a></h3><p>移除了兩個原始實現，轉而採用基於算法類型的泛型實現。過去有三個很相似的實現，這令人在選擇時感到迷惑！</p><p>庫普曼多項式（Koopman polynomial）沒有完全等價的多項式，因此已將其添加到 catalog.txt 文件中。未來更新時測試會報告此問題。</p><p>對於舊庫普曼多項式 <code>api</code> 的用戶來說，這是一個重大變化，特別是在使用自定義或非標準多項式時（Crc32 別名將繼續起作用）。編譯錯誤會說明需要做什麼才能保留現有功能，可能需要用戶進行少量代碼更改。</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> hash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Crc32WithPoly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">Castagnoli</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// old</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> hash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Crc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">Crc32Iscsi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// new</span></span></code></pre></div><p>自定義多項式需要更多的處理，並且需要用戶定義自己的算法類型。如果使用，請注意之前的實現需要預反射多項式並使用以下參數：</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">polynomial</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x741b8cd7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// equivalent to the reflected polynomial: 0xeb31d82e</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">initial</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0xffffffff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">reflect_input</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">reflect_output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">xor_output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0xffffffff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>下面是鬆散性能測量：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crc32-slicing-by-8</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 8K of tables</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   iterative:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  3074</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MiB/s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [2d191d9400000000]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  small</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keys:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  32B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  4650</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MiB/s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 152387950</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Hashes/s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [20024c446a99a300]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crc32-half-byte-lookup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 64b of tables</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   iterative:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   281</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MiB/s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [2d191d9400000000]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  small</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keys:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  32B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   389</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MiB/s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12751954</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Hashes/s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [20024c446a99a300]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crc32</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 1K of tables</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   iterative:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  3077</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MiB/s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [2d191d9400000000]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  small</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keys:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  32B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  4660</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MiB/s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 152709182</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Hashes/s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [20024c446a99a300]</span></span></code></pre></div><h3 id="重命名-comptimestringmap-為-staticstringmap" tabindex="-1">重命名 <code>ComptimeStringMap</code> 為 <code>StaticStringMap</code> <a class="header-anchor" href="#重命名-comptimestringmap-為-staticstringmap" aria-label="Permalink to &quot;重命名 `ComptimeStringMap` 為 `StaticStringMap`&quot;">​</a></h3><p>重命名後的 <code>StaticStringMap</code> 僅接受單個類型參數，並返回已知的結構類型而不是匿名結構。這些更改最初的目的是為了減少 <a href="https://github.com/ziglang/zig/pull/19682" target="_blank" rel="noreferrer">#19682</a> 中描述的“過長類型名稱”問題。</p><p>但缺點是對 API 進行了破壞，新的使用方法如下：</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> map</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">StaticStringMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initComptime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">kvs_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>更多細節：</p><ul><li>將 <code>kvs_list</code> 參數從類型參數移至 <code>initComptime()</code> 參數</li><li>新的公共方法： <ul><li><code>keys()</code> 、<code>values()</code></li><li><code>init(allocator)</code>、<code>deinit(allocator)</code> 用於運行時數據</li><li>暫時保留 <code>getLongestPrefix(str)</code>、<code>getLongestPrefixIndex(str)</code>，或許仍有用</li></ul></li><li>性能指標： <ul><li>基準測試結果：<a href="https://github.com/travisstaloch/comptime-string-map-revised/issues/1" target="_blank" rel="noreferrer">travisstaloch/comptime-string-map-revised#1</a></li><li>將結構體大小從 48 字節減少到 32 字節，從而對所有長度字段使用 <code>u32</code> 而不是 <code>usize</code>，從而提高速度</li><li>將 KV 存儲為數組結構體可提高速度</li><li>最新的基準測試顯示了 <em>debug</em> / <em>safe</em> / <em>small</em> / <em>fast</em> 的 wall_time 改進：-6.6% / -10.2% / -19.1% / -8.9%</li></ul></li></ul><h3 id="priorityqueue-存儲容量而不是長度" tabindex="-1"><code>PriorityQueue</code> 存儲容量而不是長度 <a class="header-anchor" href="#priorityqueue-存儲容量而不是長度" aria-label="Permalink to &quot;`PriorityQueue` 存儲容量而不是長度&quot;">​</a></h3><p>這是一項重大更改，使 <code>PriorityQueue</code> 與 <code>ArrayList</code> 保持一致。</p><p>此前，<code>PriorityQueue</code> 將整個分配的切片存儲在 <code>items</code> 字段中，並將長度存儲在單獨的 <code>len</code> 字段中。這與 <code>ArrayList</code> 不一致，導致訪問內存越界錯誤。</p><p>現在，<code>items</code> 字段僅指向隊列中的有效項目，額外未使用的容量存儲在單獨的 <code>cap</code> 字段中。</p><p>具體見此處：<a href="https://github.com/ziglang/zig/pull/19960" target="_blank" rel="noreferrer">std: align PriorityQueue and ArrayList API-wise</a>。</p><h3 id="重命名-std-childprocess-為-std-process-child" tabindex="-1">重命名 <code>std.ChildProcess</code> 為 <code>std.process.Child</code> <a class="header-anchor" href="#重命名-std-childprocess-為-std-process-child" aria-label="Permalink to &quot;重命名 `std.ChildProcess` 為 `std.process.Child`&quot;">​</a></h3><p>此前 <code>std.ChildProcess</code> 就已經處於棄用狀態！</p><p>升級指南：</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ChildProcess</span></span></code></pre></div><p>↓</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">process</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">Child</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>還有一些其他的函數也從 <code>std.ChildProcess</code> 移動到 <code>std.process</code> 命名空間。 未來還會有重大變化。例如，不使用創建一個 <code>Child</code>，然後在其上設置字段，然後調用 <code>spawn</code>，而是使用 <code>std.process.spawn</code> ，它採用 <code>options</code> 參數，然後返回 <code>Child</code>，只是一個從 <code>spawn</code> 到 <code>termination</code> 狀態的對象。這是在 Zig 中更傾向於採用的一種做法，即將類型設計為具有最小生命週期和儘可能少未定義字段的狀態。</p></div><h3 id="重構-cli-progress" tabindex="-1">重構 <code>CLI Progress</code> <a class="header-anchor" href="#重構-cli-progress" aria-label="Permalink to &quot;重構 `CLI Progress`&quot;">​</a></h3><p>這是對標準庫的重大更改。編譯器和構建系統都嚴重依賴此 API，因此受到影響。</p><ul><li><a href="https://asciinema.org/a/gDna9RnicwYjDRIDn4e07NFSc" target="_blank" rel="noreferrer">簡單的 <code>asciinema</code></a> <a href="https://gist.github.com/andrewrk/b22b4f663cef6b4672d7097de95ea343" target="_blank" rel="noreferrer">source code</a></li><li><a href="https://asciinema.org/a/661404" target="_blank" rel="noreferrer">使用 zig build 構建音樂播放器</a> <a href="https://codeberg.org/andrewrk/player" target="_blank" rel="noreferrer">source code</a></li><li>性能影響可以忽略不計</li></ul><p>升級指南：</p><ul><li>傳遞 <code>std.Progress.Node</code> 而不是 <code>*std.Progress.Node</code> （不再是指針）</li><li>移除對 <code>node.activate()</code> 的調用，已不再需要</li><li>現在可以直接將短存活期的字符串傳遞給 <code>Node.start</code> ，因為數據將被複制</li><li>多次初始化 <code>std.Progress</code> 是非法的，請僅在 <code>main()</code> 中進行初始化</li><li>在寫入 <code>stderr</code> 之前使用 <code>std.debug.lockStdErr</code> 和 <code>std.debug.unlockStdErr</code> 來正確集成到 <code>std.Progress</code>（ <code>std.debug.print</code> 內部已經包含該操作）</li></ul><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> progress</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">Progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ...</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> root_node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">test_fn_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>↓</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> root_node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">Progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(.{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">root_name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">estimated_total_items</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> test_fn_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p><code>start</code> 的所有選項都是可選的，當生成子進程時，首先填充 progress_node 字段：</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">child</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">progress_node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> child</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">spawn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">&gt;`std.Progress` 過去的實現存在限制，即它無法確定終端的所有權。這意味著它只能通過打印到終端的內容來處理子進程，並且它必須處理無進度感知的 stderr 寫入終端。它還禁止處理 `SIGWINCH` 和使用 `ioctl` 來查找終端的行列。</p><p></p></div><p>新實現的設計理念是，單個進程將直接控制終端，所有其他進度報告都將傳回該進程，這可以按照需求隨意定製進度條。</p><p>創建一個標準的“Zig Progress Protocol”來使用，方便當應用程序是終端所有者或者當應用程序是子進程時，<code>std.Progress</code> API 都可以正常工作。後者的進度信息將通過管道以語義方式傳遞給父進程。</p><p>文件描述符通過 <code>ZIG_PROGRESS</code> 環境變量給出，方便 <code>std.process.Child</code> 與其集成，因此在父進程中附加子進程的進度就像在調用 <code>spawn</code> 之前設置 <code>child.progress_node</code> 字段一樣簡單。</p><p>為了避免使用此 API 帶來的性能損失，<code>Node.start</code> 和 <code>Node.end</code> API 是線程安全的、無鎖的、絕對可靠的，並且執行最少量的內存加載和存儲。為了實現這一點，使用了靜態分配的 <code>Node</code> 存儲緩衝區：一塊用於父項，另外的用於其餘數據，子項不被存儲。靜態分配的緩衝區用於定製的 <code>Node</code> 分配器實現。</p><p>事實上，靜態緩衝區完全夠用，因為可以設置支持的終端寬度和高度的上限。如果終端大小超過此值，進度條輸出無論如何都會被截斷。</p><div class="tip custom-block github-alert"><p class="custom-block-title">實現的大致原理</p><p></p><p>一個單獨的線程通過計時器定期刷新終端，該進度更新線程迭代整個預分配的父數組，查找已使用的節點。這非常高效，因為雙親數組只有 200 個 8 位整數，或者大約 4 個高速緩存行。</p><p>迭代時，該線程通過從共享數據原子加載到僅由單個線程（進度更新線程）訪問的數據，將數據“序列化”到單獨的預分配數組中。</p><p>之後查找被標記為文件描述符的節點（通向子進程的管道），這些節點在序列化過程中將處理從管道中讀取的數據。除了需要重新定位的父數組之外，數據可以按位進行 <code>memcpy</code>。一旦序列化過程完成，就會有兩個路徑，一個是子進程，另一個是擁有終端的根進程。</p><p>擁有終端的根進程掃描序列化數據，計算子進程和同級指針。序列化的數據僅包含父節點，因此在計算時，會從這裡開始。然後遍歷樹，附加到一個靜態緩衝區，該緩衝區將通過單個 <code>write()</code> 系統調用發送到終端。在此過程中，會考慮檢測到的終端行和列。如果用戶調整終端大小，則會導致 <code>SIGWINCH</code> 信號，通知更新線程喚醒並使用新行和列重新繪製。</p><p>子進程並不是繪製到終端，而是獲取相同的序列化數據並通過管道發送它。管道處於非阻塞模式，因此如果管道已滿，則子進程將丟棄消息；未來的更新將包含新的進度信息。同樣，當父進程從管道中讀取消息時，它會丟棄緩衝區中除最後一條消息之外的所有消息。如果管道中沒有消息，父級將使用上次更新的數據。</p></div><p>更多信息可以見：<a href="https://andrewkelley.me/post/zig-new-cli-progress-bar-explained.html" target="_blank" rel="noreferrer">Andrew Kelley 關於該部分的 blog</a></p><h3 id="posix-iovec-使用-base-和-len-代替-iov-base-和-iov-len" tabindex="-1"><code>posix.iovec</code> 使用 <code>.base</code> 和 <code>.len</code> 代替 <code>.iov_base</code> 和 <code>.iov_len</code> <a class="header-anchor" href="#posix-iovec-使用-base-和-len-代替-iov-base-和-iov-len" aria-label="Permalink to &quot;`posix.iovec` 使用 `.base` 和 `.len` 代替 `.iov_base` 和 `.iov_len`&quot;">​</a></h3><p>升級指南：</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.{ .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">iov_base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">iov_len</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span></code></pre></div><p>↓</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.{ .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, .</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">len</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span></code></pre></div>',56)]))}const g=i(l,[["render",h]]);export{c as __pageData,g as default};
